def rf_key(name):
    if "UNIDENTIFIED" in name: return "UNIDENT"
    cid = re.search(r"C-\d+", name).group(0)
    if "prior annual" in name: return cid + "|prior"
    if "renewal" in name: return cid + "|renewal"
    return cid

prev_end = None
for m in range(1, 11):
    p = f"{D}/month_{m:02d}"
    t = json.load(open(f"{p}/trial_balance.json"))["accounts"]
    td = R2(sum(v["debit"] for v in t.values())); tc = R2(sum(v["credit"] for v in t.values()))
    assert td == tc, (m, td, tc)
    for e in json.load(open(f"{p}/journal_entries.json")):
        assert R2(sum(l["debit"] for l in e["lines"])) == R2(sum(l["credit"] for l in e["lines"])), (m, e["ref"])
    rf = json.load(open(f"{p}/deferred_revenue_rollforward.json"))
    cc = {rf_key(c["contract"]): c for c in rf["contracts"]}
    assert len(cc) == len(rf["contracts"]), f"month_{m:02d}: duplicate stable contract keys"
    for c in rf["contracts"]:
        assert R2(c["opening"] + c["billed"] - c["recognized"]) == R2(c["closing"]), (m, c["contract"])
    assert R2(sum(c["closing"] for c in rf["contracts"])) == R2(t["2200"]["credit"] - t["2200"]["debit"]), m
    if prev_end:
        for k, c in cc.items():
            if k in prev_end:
                assert R2(c["opening"]) == R2(prev_end[k]), (m, k)
            else:
                assert R2(c["opening"]) == 0.0, (m, k)  # brand-new contract must open at 0
    prev_end = {k: c["closing"] for k, c in cc.items()}

